const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const depokPt = ee.Geometry.Point([106.83, -6.39]);
  const region = depokPt.buffer(15000); // 15 km around Depok
  const scale = 1000; // use coarse scale to keep processing robust
  const maxPixels = 1e9;
  const ndviThresh = 0.3; // vegetation threshold

  // Helper: Landsat prep (scale + mask)
  function prepLandsat(image, redBand, nirBand) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
      .and(qa.bitwiseAnd(1 << 2).eq(0))      // cirrus
      .and(qa.bitwiseAnd(1 << 3).eq(0))      // cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0))      // cloud shadow
      .and(qa.bitwiseAnd(1 << 5).eq(0));     // snow
    const scaled = image.select([redBand, nirBand]).multiply(0.0000275).add(-0.2)
      .rename(['red', 'nir']);
    return scaled.updateMask(mask);
  }
  // Helper: Sentinel-2 prep (scale + mask)
  function prepS2(image) {
    // Keep SCL classes: vegetation(4), bare soils(5), water(6)
    const scl = image.select('SCL');
    const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(6));
    const scaled = image.select(['B4', 'B8']).divide(10000).rename(['red', 'nir']);
    return scaled.updateMask(mask);
  }

  // Build composite with fallbacks
  function buildComposite(year) {
    const start1 = ee.Date.fromYMD(year, 6, 1);
    const end1 = ee.Date.fromYMD(year, 10, 1);
    const start2 = ee.Date.fromYMD(year, 1, 1);
    const end2 = ee.Date.fromYMD(year, 12, 31);

    // Candidates depend on year
    const candidates = (year <= 2011)
      ? [
          {col: 'LANDSAT/LT05/C02/T1_L2', red: 'SR_B3', nir: 'SR_B4', type: 'L'},
          {col: 'LANDSAT/LT04/C02/T1_L2', red: 'SR_B3', nir: 'SR_B4', type: 'L'},
        ]
      : [
          {col: 'LANDSAT/LC08/C02/T1_L2', red: 'SR_B4', nir: 'SR_B5', type: 'L'},
          {col: 'LANDSAT/LE07/C02/T1_L2', red: 'SR_B3', nir: 'SR_B4', type: 'L'},
          {col: 'COPERNICUS/S2_SR', red: 'B4', nir: 'B8', type: 'S2'},
        ];

    function tryWindow(cand, start, end) {
      let ic = ee.ImageCollection(cand.col).filterBounds(region).filterDate(start, end);
      return ic;
    }

    // Attempt seasonal window, then full year, across candidates
    let chosen = null;
    let chosenSize = null;
    let usedWindow = null;
    for (let w = 0; w < 2; w++) {
      const start = (w === 0) ? start1 : start2;
      const end = (w === 0) ? end1 : end2;
      for (let i = 0; i < candidates.length; i++) {
        const cand = candidates[i];
        let ic = tryWindow(cand, start, end);
        const size = ic.size();
        // Use getInfo here to decide quickly
        const n = size.getInfo();
        if (n > 0) {
          chosen = {cand, ic};
          chosenSize = n;
          usedWindow = (w === 0) ? 'Jun-Oct' : 'FullYear';
          break;
        }
      }
      if (chosen) break;
    }
    if (!chosen) return {status: 'C1'};

    // Prepare composite
    let comp;
    if (chosen.cand.type === 'L') {
      const red = chosen.cand.red;
      const nir = chosen.cand.nir;
      comp = chosen.ic.map(function(img) { return prepLandsat(img, red, nir); })
                      .median();
    } else { // S2
      comp = chosen.ic.map(prepS2).median();
    }
    const ndvi = comp.normalizedDifference(['nir', 'red']).rename('ndvi');

    return {
      status: 'OK',
      ndvi: ndvi,
      images: chosenSize,
      collection: chosen.cand.col,
      window: usedWindow
    };
  }

  // Compute stats for a year
  function computeYear(year) {
    const built = buildComposite(year);
    if (built.status !== 'OK') return built;

    const ndvi = built.ndvi;
    const veg = ndvi.gt(ndviThresh).rename('veg');

    // Counts and fractions
    const validCountDict = ndvi.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: maxPixels
    });
    const totalCountDict = ee.Image.constant(1).rename('ones').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: maxPixels
    });
    const vegFracDict = veg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: maxPixels
    });

    const validPix = validCountDict.get('ndvi');
    const totalPix = totalCountDict.get('ones');
    const vegFrac = vegFracDict.get('veg');

    return {
      status: 'OK',
      images: built.images,
      collection: built.collection,
      window: built.window,
      validPix: ee.Number(validPix),
      totalPix: ee.Number(totalPix),
      vegFrac: ee.Number(vegFrac)
    };
  }

  try {
    const y1990 = computeYear(1990);
    if (y1990.status !== 'OK') {
      console.log(`1990: Images: 0`);
      console.log('C1');
      return;
    }
    const y2019 = computeYear(2019);
    if (y2019.status !== 'OK') {
      console.log(`2019: Images: 0`);
      console.log('C1');
      return;
    }

    const v1990 = {
      images: y1990.images,
      valid: y1990.validPix.getInfo(),
      total: y1990.totalPix.getInfo(),
      veg: y1990.vegFrac.getInfo(),
      col: y1990.collection,
      win: y1990.window
    };
    const v2019 = {
      images: y2019.images,
      valid: y2019.validPix.getInfo(),
      total: y2019.totalPix.getInfo(),
      veg: y2019.vegFrac.getInfo(),
      col: y2019.collection,
      win: y2019.window
    };

    // C2: No valid pixels
    if (v1990.valid === 0 || v2019.valid === 0) {
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }

    // C3: invalid results
    function invalid(x) {
      return (x === null || x === undefined || isNaN(x) || x < 0 || x > 1);
    }
    if (invalid(v1990.veg) || invalid(v2019.veg)) {
      console.log('Invalid vegetation fraction.');
      console.log('C3');
      return;
    }

    const validPct1990 = 100 * (v1990.valid / v1990.total);
    const validPct2019 = 100 * (v2019.valid / v2019.total);

    // Evidence lines
    console.log(`1990 [${v1990.col}, ${v1990.win}]: Images=${v1990.images}, ValidPix=${v1990.valid}/${v1990.total} (${validPct1990.toFixed(1)}%), VegCover=${(v1990.veg*100).toFixed(1)}%`);
    console.log(`2019 [${v2019.col}, ${v2019.win}]: Images=${v2019.images}, ValidPix=${v2019.valid}/${v2019.total} (${validPct2019.toFixed(1)}%), VegCover=${(v2019.veg*100).toFixed(1)}%`);
    const deltaPct = (v2019.veg - v1990.veg) * 100;
    console.log(`Δ VegCover (2019-1990) = ${deltaPct.toFixed(1)} pp`);

    // Final answer
    if (v2019.veg < v1990.veg) {
      console.log('A'); // Yes
    } else {
      console.log('B'); // No
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
